SELECT st.tx_hash, st.payer AS chain_payer, s.payer AS receipt_payer, st.seller AS chain_seller, s.seller AS receipt_seller, st.amount_atomic AS chain_amount, s.amount_atomic AS receipt_amount, CASE WHEN LOWER(st.payer) = LOWER(s.payer) THEN 1 ELSE 0 END AS payer_match, CASE WHEN LOWER(st.seller) = LOWER(s.seller) THEN 1 ELSE 0 END AS seller_match, CASE WHEN st.amount_atomic = s.amount_atomic THEN 1 ELSE 0 END AS amount_match, st.status FROM settlements st INNER JOIN sales s ON LOWER(st.tx_hash) = LOWER(s.tx_hash) ORDER BY st.tx_hash
